"""Complete CNS infections with opportunistic, focal and toxin-related disease."""
from create_cns_infections import rows,q
from qbank_authoring import ref,finalize
CR=ref('NIH Adult/Adolescent HIV OI Guideline: Cryptococcosis','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/cryptococcosis')
TX=ref('NIH Adult/Adolescent HIV OI Guideline: Toxoplasmosis','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/toxoplasmosis')
JC=ref('NIH Adult/Adolescent HIV OI Guideline: PML','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/progressive')
AB=ref('ESCMID Brain Abscess Guideline, 2024','https://doi.org/10.1016/j.cmi.2023.08.016')
NC=ref('IDSA/ASTMH Neurocysticercosis Guideline','https://www.idsociety.org/practice-guideline/neurocysticercosis/')
RA=ref('CDC Rabies Postexposure Prophylaxis Guidance','https://www.cdc.gov/rabies/hcp/clinical-care/post-exposure-prophylaxis.html')
TE=ref('CDC Clinical Care of Tetanus','https://www.cdc.gov/tetanus/hcp/clinical-care/index.html')

q('Advanced HIV is accompanied by subacute headache, raised CSF pressure and positive CSF cryptococcal antigen. Which diagnosis is most likely?', 'Cryptococcal meningitis',[
 ('An absence of marked neck stiffness excludes meningitis','Cryptococcal disease can have subtle meningeal signs.'),('A normal low CSF cell count excludes opportunistic disease','Profound immune suppression can limit pleocytosis.'),('Primary migraine explains the antigen result','A compatible CNS antigen-positive syndrome needs treatment.')],
 'Immune suppression changes the inflammatory presentation', '**Cryptococcosis can cause meningitis with limited clinical or CSF inflammation.**', ['Measure opening pressure and obtain appropriate cultures.','Blood and other organ involvement may coexist.'], '**Treat infection and pressure together.**', ['Antifungal therapy alone may not control raised ICP.','Monitor neurological and visual symptoms.'], [['Test','CSF cryptococcal antigen'],['Pressure','Important complication'],['Inflammation','May be modest']], [CR], 'clinical_scenario')
q('Cryptococcal meningitis causes headache and markedly elevated opening pressure. Which intervention is central to pressure management?', 'Therapeutic CSF drainage with repeat assessment and further drainage or diversion when indicated',[
 ('Acetazolamide as routine replacement for therapeutic drainage','It is not the recommended standard strategy.'),('Routine corticosteroids for every elevated pressure','They are not standard pressure treatment in ordinary cryptococcal meningitis.'),('Ignore pressure if fungal cultures improve','Pressure can remain dangerous despite microbiological response.')],
 'Pressure is an independent treatment target', '**Therapeutic LP can be life-saving when indicated.**', ['Use a protocol-based drainage target and repeated reassessment.','Selected refractory cases need lumbar drainage or shunting.'], '**Investigate neurological worsening.**', ['Assess pressure, relapse, treatment failure and IRIS.','Do not reflexively attribute every decline to ongoing fungal growth.'], [['Antifungal','Controls organism'],['CSF drainage','Controls pressure'],['Persistent decline','Reassess mechanism']], [CR])
q('In a resource-rich setting, which is a preferred NIH induction regimen for HIV-associated cryptococcal meningitis?', 'Liposomal amphotericin B plus flucytosine for two weeks',[
 ('Fluconazole maintenance dosing alone as equivalent induction','This is not the preferred high-resource induction regimen.'),('Acyclovir alone','It has no appropriate anticryptococcal activity.'),('Steroid monotherapy','This does not treat the fungus.')],
 'Induction and maintenance have different goals', '**Initial fungicidal combination treatment is followed by consolidation and maintenance therapy.**', ['Alternative validated regimens apply in other resource contexts.','Flucytosine and amphotericin require blood, renal and electrolyte monitoring.'], '**Use the exact guideline for the setting.**', ['Adjust doses for relevant organ function.','Do not confuse a WHO simplified regimen with an incomplete version of another protocol.'], [['Induction','Fungicidal combination'],['Consolidation','Usually fluconazole-based'],['Monitoring','Renal, electrolytes and blood counts']], [CR])
q('When is ART generally initiated in a patient newly diagnosed with HIV-associated CNS cryptococcosis?', 'Usually deferred about four to six weeks after antifungal treatment begins, with individualized specialist planning',[
 ('Always on the first day regardless of CNS infection','Very early ART can increase harmful inflammatory complications.'),('Never, because HIV treatment has no benefit','ART remains essential after appropriate timing.'),('Only after permanent loss of all immune function','This has no clinical basis.')],
 'The timing rule differs from many other opportunistic infections', '**Early CNS immune reconstitution can cause dangerous inflammation.**', ['The plan considers clinical and microbiological response.','Pregnancy and other circumstances require expert risk balancing.'], '**Do not generalize this delay to every HIV infection.**', ['Some OIs favor prompt ART.','Maintain pressure control and antifungal adherence during the interval.'], [['CNS cryptococcus','Usually 4–6 week delay'],['Reason','IRIS/mortality concern'],['Long term','ART essential']], [CR])
q('A patient with CD4 count 35 has subacute focal weakness and multiple ring-enhancing lesions, including basal ganglia, with positive Toxoplasma IgG. Which cause is especially likely?', 'Toxoplasma encephalitis',[
 ('PML as the typical mass-effect ring-enhancing pattern','PML usually has a white-matter demyelinating pattern without this typical mass effect.'),('Primary CNS lymphoma is impossible','It remains a key competing diagnosis.'),('A positive IgG alone proves every lesion is toxoplasma','It supports prior exposure but the entire syndrome determines probability.')],
 'The lesion pattern and immune context guide initial management', '**Reactivated toxoplasmosis commonly causes focal encephalitis in advanced HIV.**', ['Lymphoma, TB and fungal lesions remain alternatives.','Serology, imaging and treatment response help assessment.'], '**Use a structured diagnostic-treatment plan.**', ['Atypical findings or poor response can require biopsy.','Manage edema or seizures when clinically indicated.'], [['Context','Advanced immune suppression'],['Pattern','Often multiple enhancing lesions'],['Differential','Lymphoma, TB and fungi']], [TX], 'clinical_scenario')
q('Which is an appropriate treatment approach for HIV-associated toxoplasma encephalitis?', 'Pyrimethamine with sulfadiazine and leucovorin, or a guideline-supported alternative such as TMP-SMX',[
 ('Pyrimethamine without leucovorin regardless of marrow toxicity','Leucovorin protects against folate-antagonist marrow effects.'),('Fluconazole alone','This is not toxoplasma-directed therapy.'),('Acyclovir alone','It does not treat this protozoal infection.')],
 'Combination treatment targets the organism while managing toxicity', '**Leucovorin is essential with pyrimethamine-containing regimens.**', ['TMP-SMX is an established alternative in current NIH guidance.','Treatment and secondary maintenance depend on response and immune recovery.'], '**Reassess early improvement.**', ['Lack of expected response raises an alternative diagnosis or treatment problem.','Monitor blood counts and organ-specific adverse effects.'], [['Pyrimethamine regimen','Include leucovorin'],['Alternative','TMP-SMX when appropriate'],['Poor response','Diagnostic reassessment']], [TX])
q('Which HIV patient has a standard indication for primary toxoplasma prophylaxis?', 'A Toxoplasma-IgG-positive patient with CD4 count below 100 cells/mm³',[
 ('Every HIV patient regardless of serology or immune status','Prophylaxis is risk-targeted.'),('Only after a first encephalitis episode','That would be secondary rather than primary prevention.'),('Only if a brain lesion is already present','Primary prophylaxis precedes disease.')],
 'Serostatus and immune deficit define reactivation risk', '**TMP-SMX is a preferred prophylactic option in eligible patients.**', ['It can simultaneously provide Pneumocystis protection.','Alternative regimens have specific eligibility and toxicity requirements.'], '**Reassess after immune recovery.**', ['Stopping and restarting follow current CD4/viral-suppression criteria.','Do not assume every alternative PCP regimen also protects against toxoplasma.'], [['IgG','Prior exposure'],['CD4','Below 100'],['Preferred prophylaxis','TMP-SMX']], [TX])
q('Advanced HIV is accompanied by steadily progressive focal deficits and asymmetric white-matter lesions with little mass effect. Which diagnosis is especially important?', 'Progressive multifocal leukoencephalopathy',[
 ('Typical toxoplasmosis as the obligatory explanation','The nonmass-like white-matter pattern favors PML consideration.'),('A normal peripheral blood count excludes infection','It does not assess JCV CNS disease.'),('A single normal early CSF JCV result always excludes PML','Sensitivity depends on context and repeat assessment may be required.')],
 'JCV causes a demyelinating opportunistic syndrome', '**PML commonly produces progressive focal dysfunction corresponding to white-matter lesions.**', ['CSF JCV PCR supports diagnosis.','IRIS can alter the imaging and clinical picture.'], '**Restore immune control when possible.**', ['Effective ART is central in HIV-associated PML.','There is no established universally effective direct anti-JCV antiviral.'], [['Agent','JC virus'],['Pattern','White-matter demyelination'],['HIV treatment','Effective ART']], [JC], 'clinical_scenario')
q('Fever and focal deficits occur with a ring-enhancing lesion showing central diffusion restriction. What diagnosis merits urgent assessment?', 'Brain abscess',[
 ('The image proves a benign incidental cyst','The clinical and diffusion findings require infection assessment.'),('LP is automatically the first and safest test with mass effect','LP can be hazardous and low-yield in focal mass lesions.'),('All ring lesions are toxoplasma regardless of immune status','The differential is wider.')],
 'A focal suppurative lesion needs a different pathway from uncomplicated meningitis', '**MRI and neurosurgical/infectious-disease assessment are central.**', ['Culture from aspiration or excision can identify the pathogen.','Dental, sinus, ear, cardiac and hematogenous sources may be relevant.'], '**Assess pressure and rupture risk.**', ['Severe disease requires prompt antimicrobial and surgical decisions.','Do not delay unstable-patient treatment merely to improve culture yield.'], [['MRI','Defines lesion and complications'],['Tissue','Can identify organism'],['LP','Often inappropriate with focal mass effect']], [AB], 'clinical_scenario')
q('What should guide empiric brain-abscess antimicrobial selection?', 'Likely source, host immune status, prior neurosurgery and local microbiology, with subsequent culture-directed treatment',[
 ('One identical regimen for community dental disease and recent neurosurgery','The likely organisms differ.'),('Drainage eliminates the need for all antimicrobials','Combined care is commonly required.'),('A short oral analgesic course is definitive therapy','This does not treat infection.')],
 'Source predicts the microbial spectrum', '**Community-acquired abscess often needs streptococcal and anaerobic coverage.**', ['Postoperative and immunocompromised settings need different consideration.','Aspiration or excision is recommended when feasible except in defined circumstances.'], '**Use a coordinated treatment-duration plan.**', ['Clinical and imaging follow-up guide progress.','Corticosteroids are reserved for selected severe edema or pressure situations rather than every abscess.'], [['Source','Guides coverage'],['Drainage','Diagnosis and source control'],['Follow-up','Clinical and imaging response']], [AB])
q('What is an essential principle before antiparasitic treatment for neurocysticercosis?', 'Classify lesion stage and location, assess intracranial pressure and exclude ocular involvement',[
 ('Treat every calcification and ventricular cyst with the same immediate regimen','Management differs substantially.'),('Skip funduscopic assessment because eye cysts cannot be harmed','Inflammation from treatment can threaten vision.'),('Antiparasitics replace treatment of hydrocephalus','Pressure and obstruction may need priority treatment.')],
 'Parasite killing can provoke clinically important inflammation', '**Viable parenchymal, calcified, ventricular and subarachnoid disease have different pathways.**', ['MRI and noncontrast CT provide complementary information.','IDSA recommends funduscopic examination before anthelminthic therapy.'], '**Stabilize complications first.**', ['Treat seizures and hydrocephalus appropriately.','Use corticosteroid cover when indicated with antiparasitic therapy.'], [['Stage/location','Determines management'],['Eyes','Examine before therapy'],['Pressure','May require priority intervention']], [NC])
q('A patient has seizures associated with only calcified parenchymal neurocysticercosis lesions. What is the usual treatment principle?', 'Treat the seizure disorder and complications rather than giving antiparasitics to kill already calcified lesions',[
 ('Calcification proves a viable cyst requiring routine albendazole','Calcified lesions are not viable parasites.'),('All seizures will stop permanently without treatment','Calcified lesions can remain epileptogenic.'),('Routine antiparasitic therapy reverses every calcification','That is not the recommended approach.')],
 'Lesion stage changes the biological target', '**Calcified parenchymal disease generally receives symptomatic management rather than antiparasitic treatment.**', ['Perilesional edema may occur.','MRI can identify additional lesions or complications when indicated.'], '**Manage epilepsy according to the clinical course.**', ['Drug choice and duration depend on recurrence risk.','Refractory cases can need specialized assessment.'], [['Calcified lesion','Nonviable'],['Primary target','Seizures and complications'],['Antiparasitic','Not routine for isolated calcified disease']], [NC], 'clinical_scenario')
q('After a potentially rabid animal bite in a previously unvaccinated person, what is the appropriate prevention principle?', 'Prompt wound cleansing and exposure-based vaccine plus rabies immunoglobulin when indicated',[
 ('Wait for neurological symptoms before prophylaxis','Clinical rabies is usually fatal; prevention must precede symptoms.'),('Vaccination alone always replaces local wound care and immunoglobulin','The appropriate unvaccinated exposure pathway includes both active and passive measures.'),('All previously vaccinated patients require the identical unvaccinated regimen','Prior vaccination changes the schedule and immunoglobulin indication.')],
 'Postexposure prophylaxis prevents neuroinvasive disease', '**Use the local WHO/CDC-compatible exposure and vaccination pathway.**', ['Infiltrate indicated immunoglobulin into and around wounds appropriately.','US and WHO schedules differ by route and setting.'], '**Do not delay expert risk assessment.**', ['Animal species, availability for observation/testing and exposure type matter.','Immune compromise can change the schedule and follow-up.'], [['Wound','Clean promptly'],['Active protection','Vaccine'],['Passive protection','Immunoglobulin when indicated']], [RA], 'clinical_scenario')
q('Trismus and stimulus-induced generalized spasms develop after a contaminated wound. Which management principle is appropriate?', 'Treat suspected tetanus with antitoxin, wound care, appropriate antibiotics, spasm/autonomic support and vaccination',[
 ('Natural infection guarantees future immunity','Tetanus does not reliably confer protection.'),('Antibiotics alone reverse all bound toxin','They do not neutralize already bound neurotoxin.'),('Preserved awareness makes tetanus impossible','Consciousness can be preserved during painful spasms.')],
 'Toxin neutralization and supportive care have different roles', '**Tetanus immune globulin neutralizes unbound toxin.**', ['Debridement and antibiotics reduce ongoing bacterial toxin production.','Airway, spasm and autonomic care may require ICU support.'], '**Provide active immunization during recovery.**', ['Do not infer protection from having survived disease.','Review the wound and vaccination history.'], [['TIG','Unbound toxin'],['Antibiotic/wound care','Reduce source'],['Vaccine','Future protection']], [TE], 'clinical_scenario')

if __name__=='__main__':finalize('Neurology',13,'CNS Infections','neuro-cns-infections',rows,28)
